/*
 * Главный тестовый файл для C51
 * Запускает все тесты для AT89S4051
 * Соответствует стандарту C89
 */

#include "common.h"

/* Главная функция */
void main(void) {
    /* Инициализация системы */
    port_init();

    /* Индикация начала тестирования */
    P1 = 0x00;

    /* Запуск тестов памяти */
    test_memory_types();

    /* Небольшая задержка между тестами */
    {
        unsigned int delay;
        for (delay = 0; delay < 5000; delay++) {
            /* Пустой цикл */
        }
    }

    /* Запуск тестов битовых операций */
    test_bit_operations();

    /* Задержка */
    {
        unsigned int delay;
        for (delay = 0; delay < 5000; delay++) {
            /* Пустой цикл */
        }
    }

    /* Запуск тестов таймеров */
    test_timer_operations();

    /* Задержка */
    {
        unsigned int delay;
        for (delay = 0; delay < 5000; delay++) {
            /* Пустой цикл */
        }
    }

    /* Запуск тестов портов */
    test_port_operations();

    /* Задержка */
    {
        unsigned int delay;
        for (delay = 0; delay < 5000; delay++) {
            /* Пустой цикл */
        }
    }

    /* Запуск тестов прерываний */
    test_interrupt_setup();

    /* Финальная индикация завершения всех тестов */
    P1 = 0xFF;

    /* Бесконечный цикл */
    while (1) {
        /* Программа завершена, ожидание */
    }
}

/*
 * Тест битовых операций в C51
 * Демонстрирует работу с битовыми переменными и операциями
 * Соответствует стандарту C89
 */

#include "common.h"

/* Битовые переменные - уникальная особенность C51 */
bit system_ready;
bit error_flag;
bit test_mode;

/* Тест основных битовых операций */
void test_bit_operations(void) {
    unsigned char test_byte;
    unsigned char result;

    /* Инициализация тестового байта */
    test_byte = 0x00;

    /* Тест установки битов */
    SET_BIT(test_byte, 0);
    SET_BIT(test_byte, 2);
    SET_BIT(test_byte, 4);
    SET_BIT(test_byte, 6);

    /* Проверка результата (должно быть 0x55) */
    if (test_byte == 0x55) {
        SET_BIT(P1, 0);  /* Тест установки битов пройден */
    }

    /* Тест сброса битов */
    CLEAR_BIT(test_byte, 0);
    CLEAR_BIT(test_byte, 4);

    /* Проверка результата (должно быть 0x44) */
    if (test_byte == 0x44) {
        SET_BIT(P1, 1);  /* Тест сброса битов пройден */
    }

    /* Тест инверсии битов */
    TOGGLE_BIT(test_byte, 1);
    TOGGLE_BIT(test_byte, 3);
    TOGGLE_BIT(test_byte, 5);
    TOGGLE_BIT(test_byte, 7);

    /* Проверка результата (должно быть 0xEE) */
    if (test_byte == 0xEE) {
        SET_BIT(P1, 2);  /* Тест инверсии битов пройден */
    }

    /* Тест проверки битов */
    result = 0;
    if (TEST_BIT(test_byte, 1)) result |= 0x01;
    if (TEST_BIT(test_byte, 3)) result |= 0x02;
    if (TEST_BIT(test_byte, 5)) result |= 0x04;
    if (TEST_BIT(test_byte, 7)) result |= 0x08;

    /* Все проверяемые биты должны быть установлены */
    if (result == 0x0F) {
        SET_BIT(P1, 3);  /* Тест проверки битов пройден */
    }
}

/* Тест работы с битовыми переменными C51 */
void test_bit_variables(void) {
    /* Инициализация битовых переменных */
    system_ready = 0;
    error_flag = 0;
    test_mode = 1;

    /* Логические операции с битовыми переменными */
    if (test_mode && !error_flag) {
        system_ready = 1;
    }

    /* Проверка результата */
    if (system_ready) {
        SET_BIT(P1, 4);  /* Тест битовых переменных пройден */
    }

    /* Тест условных операций */
    error_flag = system_ready && test_mode;
    if (error_flag) {
        SET_BIT(P1, 5);  /* Тест условных операций пройден */
    }
}

/* Тест работы с регистрами специальных функций */
void test_sfr_bits(void) {
    /* Сохранение исходного состояния */
    unsigned char original_p1 = P1;

    /* Тест установки отдельных битов порта */
    P1_0 = 1;  /* Установка бита 0 порта P1 */
    P1_1 = 0;  /* Сброс бита 1 порта P1 */
    P1_2 = 1;  /* Установка бита 2 порта P1 */

    /* Проверка состояния битов */
    if (P1_0 && !P1_1 && P1_2) {
        SET_BIT(P1, 6);  /* Тест SFR битов пройден */
    }

    /* Восстановление исходного состояния */
    P1 = original_p1;
}

/* Демонстрация эффективного использования битов */
void bit_manipulation_demo(void) {
    unsigned char status_register;
    unsigned char mask;

    /* Создание маски для работы с несколькими битами */
    mask = 0x0F;  /* Маска для младших 4 битов */

    /* Установка статусного регистра */
    status_register = 0xA5;

    /* Очистка младших 4 битов */
    status_register &= ~mask;

    /* Установка новых значений в младшие 4 бита */
    status_register |= (0x0C & mask);

    /* Проверка результата (должно быть 0xAC) */
    if (status_register == 0xAC) {
        SET_BIT(P1, 7);  /* Демонстрация битовых операций пройдена */
    }
}

/*
 * Тест настройки прерываний в C51
 * Демонстрирует работу с внешними прерываниями и прерываниями таймеров
 * Соответствует стандарту C89
 */

#include "common.h"

/* Глобальные переменные для обработки прерываний */
unsigned char interrupt_counter = 0;
bit timer_interrupt_flag = 0;
bit external_interrupt_flag = 0;

/* Обработчик прерывания Timer0 */
void timer0_isr(void) interrupt 1 {
    /* Сброс флага переполнения таймера */
    TF0 = 0;

    /* Увеличение счетчика прерываний */
    interrupt_counter++;

    /* Установка флага */
    timer_interrupt_flag = 1;

    /* Индикация на порту */
    TOGGLE_BIT(P1, 0);
}

/* Обработчик внешнего прерывания INT0 */
void external_int0_isr(void) interrupt 0 {
    /* Сброс флага прерывания */
    IE0 = 0;

    /* Установка флага */
    external_interrupt_flag = 1;

    /* Индикация на порту */
    TOGGLE_BIT(P1, 1);
}

/* Инициализация системы прерываний */
void interrupt_system_init(void) {
    /* Запрет всех прерываний */
    EA = 0;

    /* Очистка всех флагов прерываний */
    TF0 = 0;
    TF1 = 0;
    IE0 = 0;
    IE1 = 0;

    /* Сброс счетчиков */
    interrupt_counter = 0;
    timer_interrupt_flag = 0;
    external_interrupt_flag = 0;
}

/* Настройка прерывания Timer0 */
void setup_timer0_interrupt(void) {
    /* Остановка таймера */
    TR0 = 0;

    /* Настройка режима таймера */
    TMOD &= 0xF0;  /* Очистка битов Timer0 */
    TMOD |= 0x01;  /* Режим 1: 16-битный таймер */

    /* Загрузка начального значения для переполнения через ~50мс при 12МГц */
    TH0 = 0x3C;    /* Старший байт */
    TL0 = 0xB0;    /* Младший байт */

    /* Разрешение прерывания Timer0 */
    ET0 = 1;

    /* Сброс флага */
    TF0 = 0;

    /* Запуск таймера */
    TR0 = 1;
}

/* Настройка внешнего прерывания INT0 */
void setup_external_int0(void) {
    /* Настройка типа прерывания INT0 по спаду */
    IT0 = 1;  /* Прерывание по фронту */

    /* Сброс флага прерывания */
    IE0 = 0;

    /* Разрешение прерывания INT0 */
    EX0 = 1;
}

/* Тест системы прерываний */
void test_interrupt_setup(void) {
    unsigned char test_timeout;

    /* Инициализация системы прерываний */
    interrupt_system_init();

    /* Настройка прерывания таймера */
    setup_timer0_interrupt();

    /* Разрешение глобальных прерываний */
    EA = 1;

    /* Ожидание срабатывания прерывания таймера */
    test_timeout = 0;
    while (!timer_interrupt_flag && test_timeout < 200) {
        test_timeout++;
        /* Простая задержка */
        {
            unsigned int delay;
            for (delay = 0; delay < 100; delay++) {
                /* Пустой цикл */
            }
        }
    }

    /* Проверка работы прерывания таймера */
    if (timer_interrupt_flag) {
        SET_BIT(P1, 2);  /* Прерывание таймера работает */
    }

    /* Настройка внешнего прерывания */
    setup_external_int0();

    /* Симуляция внешнего прерывания (программная установка флага) */
    IE0 = 1;  /* Программная установка флага INT0 */

    /* Небольшая задержка для обработки */
    {
        unsigned int delay;
        for (delay = 0; delay < 1000; delay++) {
            /* Пустой цикл */
        }
    }

    /* Проверка обработки внешнего прерывания */
    if (external_interrupt_flag) {
        SET_BIT(P1, 3);  /* Внешнее прерывание работает */
    }
}

/* Демонстрация приоритетов прерываний */
void interrupt_priority_demo(void) {
    /* Установка высокого приоритета для INT0 */
    PX0 = 1;  /* Высокий приоритет для внешнего прерывания 0 */

    /* Установка низкого приоритета для Timer0 */
    PT0 = 0;  /* Низкий приоритет для таймера 0 */

    /* Разрешение прерываний */
    EX0 = 1;  /* Внешнее прерывание 0 */
    ET0 = 1;  /* Прерывание таймера 0 */
    EA = 1;   /* Глобальное разрешение */

    /* Индикация настройки приоритетов */
    SET_BIT(P1, 4);
}

/* Тест маскирования прерываний */
void interrupt_mask_test(void) {
    /* Запрет всех прерываний */
    EA = 0;

    /* Установка флагов прерываний программно */
    TF0 = 1;
    IE0 = 1;

    /* Проверка, что прерывания не обрабатываются */
    {
        unsigned int delay;
        for (delay = 0; delay < 1000; delay++) {
            /* Пустой цикл */
        }
    }

    /* Если флаги остались установленными, маскирование работает */
    if (TF0 && IE0) {
        SET_BIT(P1, 5);  /* Маскирование работает */
    }

    /* Разрешение прерываний */
    EA = 1;

    /* Небольшая задержка для обработки */
    {
        unsigned int delay;
        for (delay = 0; delay < 1000; delay++) {
            /* Пустой цикл */
        }
    }

    /* Проверка обработки отложенных прерываний */
    if (!TF0 || !IE0) {
        SET_BIT(P1, 6);  /* Отложенные прерывания обработаны */
    }
}

/*
 * Тест различных типов памяти в C51
 * Демонстрирует работу с data, idata, xdata и code памятью
 * Соответствует стандарту C89
 */

#include "common.h"

/* Переменные в различных типах памяти */
unsigned char INTERNAL_DATA internal_var = 0x55;           /* Внутренняя RAM (прямая адресация) */
unsigned char INDIRECT_DATA indirect_var = 0xAA;           /* Внутренняя RAM (косвенная адресация) */
unsigned char EXTERNAL_DATA external_var = 0x33;           /* Внешняя RAM (если доступна) */

/* Константы в программной памяти */
unsigned char CODE_MEMORY lookup_table[] = {
    0x00, 0x11, 0x22, 0x33, 0x44, 0x55, 0x66, 0x77,
    0x88, 0x99, 0xAA, 0xBB, 0xCC, 0xDD, 0xEE, 0xFF
};

/* Массив в стеке (автоматические переменные) */
void test_stack_memory(void) {
    unsigned char local_array[8];  /* Локальный массив в стеке */
    unsigned char i;

    /* Инициализация локального массива */
    for (i = 0; i < 8; i++) {
        local_array[i] = i * 2;
    }

    /* Проверка корректности записи */
    if (local_array[3] == 6 && local_array[7] == 14) {
        TEST_PASS();
    } else {
        TEST_FAIL();
    }
}

/* Тест работы с различными типами памяти */
void test_memory_types(void) {
    unsigned char temp_value;
    unsigned char INTERNAL_DATA *data_ptr;
    unsigned char CODE_MEMORY *code_ptr;

    /* Тест внутренней памяти (data) */
    internal_var = 0x12;
    if (internal_var == 0x12) {
        SET_BIT(P1, 0);  /* Сигнал успеха на бит 0 порта P1 */
    }

    /* Тест косвенной адресации (idata) */
    indirect_var = 0x34;
    if (indirect_var == 0x34) {
        SET_BIT(P1, 1);  /* Сигнал успеха на бит 1 порта P1 */
    }

    /* Тест чтения из программной памяти (code) */
    temp_value = lookup_table[5];  /* Должно быть 0x55 */
    if (temp_value == 0x55) {
        SET_BIT(P1, 2);  /* Сигнал успеха на бит 2 порта P1 */
    }

    /* Тест работы с указателями на различные типы памяти */
    data_ptr = &internal_var;
    code_ptr = lookup_table;

    if (*data_ptr == 0x12 && code_ptr[0] == 0x00) {
        SET_BIT(P1, 3);  /* Сигнал успеха на бит 3 порта P1 */
    }

    /* Тест стековой памяти */
    test_stack_memory();

    /* Финальная проверка - если все биты установлены */
    if ((P1 & 0x0F) == 0x0F) {
        P1 = 0xAA;  /* Все тесты пройдены */
    } else {
        P1 = 0x55;  /* Есть ошибки */
    }
}

/* Демонстрация эффективного использования памяти */
void memory_optimization_demo(void) {
    bit flag1, flag2, flag3;  /* Использование битовых переменных для экономии памяти */
    TestData8051 INTERNAL_DATA test_data;  /* Упаковка данных в структуру */

    test_data.id = 1;
    test_data.status = 0x80;
    test_data.value = 0x1234;

    /* Работа с битовыми флагами */
    flag1 = 1;
    flag2 = 0;
    flag3 = flag1 && !flag2;

    if (flag3 && test_data.id == 1) {
        TOGGLE_BIT(P1, 7);  /* Индикация успешного теста оптимизации */
    }
}

/*
 * Тест операций с портами ввода-вывода в C51
 * Демонстрирует работу с портами P1, P3 на AT89S4051
 * Соответствует стандарту C89
 */

#include "common.h"

/* Глобальные переменные для работы с портами */
unsigned char port_test_pattern = 0x55;
bit port_test_flag = 0;

/* Инициализация портов */
void port_init(void) {
    /* Инициализация P1 как выходной порт */
    P1 = 0xFF;  /* Установка всех линий в высокий уровень */

    /* P3 используется для специальных функций на AT89S4051 */
    /* P3.0 - RXD, P3.1 - TXD, P3.2 - INT0, P3.3 - INT1 */
    /* P3.4 - T0, P3.5 - T1 */
}

/* Чтение порта P1 */
unsigned char read_port1(void) {
    return P1;
}

/* Запись в порт P1 */
void write_port1(unsigned char value) {
    P1 = value;
}

/* Тест основных операций с портами */
void test_port_operations(void) {
    unsigned char test_value;
    unsigned char original_value;

    /* Сохранение исходного состояния */
    original_value = P1;

    /* Тест записи в порт */
    write_port1(0xAA);
    test_value = read_port1();

    if (test_value == 0xAA) {
        SET_BIT(P1, 0);  /* Тест записи пройден */
    }

    /* Тест инверсии */
    write_port1(0x55);
    test_value = read_port1();

    if (test_value == 0x55) {
        SET_BIT(P1, 1);  /* Тест инверсии пройден */
    }

    /* Тест установки отдельных битов */
    write_port1(0x00);
    SET_BIT(P1, 2);
    SET_BIT(P1, 4);
    SET_BIT(P1, 6);

    test_value = read_port1();
    if ((test_value & 0x54) == 0x54) {
        SET_BIT(P1, 3);  /* Тест установки битов пройден */
    }
}

/* Тест работы с отдельными битами порта */
void test_port_bits(void) {
    /* Очистка порта */
    P1 = 0x00;

    /* Тест установки отдельных битов через битовые переменные */
    P1_0 = 1;
    P1_2 = 1;
    P1_4 = 1;
    P1_6 = 1;

    /* Проверка результата */
    if (P1 == 0x55) {
        P1_7 = 1;  /* Индикация успеха */
    }

    /* Тест сброса битов */
    P1_0 = 0;
    P1_4 = 0;

    if (P1 == 0xA4) {
        P1_1 = 1;  /* Индикация успеха сброса */
    }
}

/* Демонстрация сканирования портов */
void port_scan_demo(void) {
    unsigned char i;
    unsigned char pattern;

    /* Бегущий огонек */
    pattern = 0x01;
    for (i = 0; i < 8; i++) {
        P1 = pattern;
        pattern = pattern << 1;

        /* Простая задержка */
        {
            unsigned int delay;
            for (delay = 0; delay < 1000; delay++) {
                /* Пустой цикл */
            }
        }
    }

    /* Обратный бегущий огонек */
    pattern = 0x80;
    for (i = 0; i < 8; i++) {
        P1 = pattern;
        pattern = pattern >> 1;

        /* Простая задержка */
        {
            unsigned int delay;
            for (delay = 0; delay < 1000; delay++) {
                /* Пустой цикл */
            }
        }
    }
}

/* Тест чтения входных сигналов */
void test_input_reading(void) {
    unsigned char input_state;

    /* Установка порта в режим ввода (все биты в 1) */
    P1 = 0xFF;

    /* Чтение состояния порта */
    input_state = P1;

    /* Анализ входных сигналов */
    if (TEST_BIT(input_state, 0)) {
        /* Бит 0 установлен */
        port_test_flag = 1;
    }

    if (TEST_BIT(input_state, 7)) {
        /* Бит 7 установлен */
        TOGGLE_BIT(P1, 1);
    }
}

/* Демонстрация работы с масками портов */
void port_mask_demo(void) {
    unsigned char mask_lower;
    unsigned char mask_upper;
    unsigned char port_value;

    mask_lower = 0x0F;  /* Маска для младших 4 битов */
    mask_upper = 0xF0;  /* Маска для старших 4 битов */

    /* Установка только младших битов */
    P1 = 0x00;
    P1 |= (0x0A & mask_lower);

    /* Установка только старших битов */
    P1 |= (0x50 & mask_upper);

    port_value = P1;

    /* Проверка результата */
    if (port_value == 0x5A) {
        TOGGLE_BIT(P1, 7);  /* Индикация успеха */
    }
}

/*
 * Тест операций с таймерами в C51
 * Демонстрирует работу с Timer0 и Timer1 на AT89S4051
 * Соответствует стандарту C89
 */

#include "common.h"

/* Глобальные переменные для работы с таймерами */
unsigned int timer0_overflow_count = 0;
unsigned int timer1_overflow_count = 0;
bit timer0_flag = 0;
bit timer1_flag = 0;

/* Инициализация Timer0 в режиме 1 (16-битный) */
void timer0_init(unsigned int reload_value) {
    /* Остановка таймера */
    TR0 = 0;

    /* Режим 1: 16-битный таймер/счетчик */
    TMOD &= 0xF0;  /* Очистка младших 4 битов */
    TMOD |= 0x01;  /* Установка режима 1 для Timer0 */

    /* Загрузка начального значения */
    TH0 = (unsigned char)(reload_value >> 8);    /* Старший байт */
    TL0 = (unsigned char)(reload_value & 0xFF);  /* Младший байт */

    /* Сброс флага переполнения */
    TF0 = 0;

    /* Запуск таймера */
    TR0 = 1;
}

/* Инициализация Timer1 в режиме 2 (8-битный с автоперезагрузкой) */
void timer1_init(unsigned int reload_value) {
    /* Остановка таймера */
    TR1 = 0;

    /* Режим 2: 8-битный с автоперезагрузкой */
    TMOD &= 0x0F;  /* Очистка старших 4 битов */
    TMOD |= 0x20;  /* Установка режима 2 для Timer1 */

    /* Загрузка значения перезагрузки */
    TH1 = (unsigned char)(reload_value & 0xFF);
    TL1 = (unsigned char)(reload_value & 0xFF);

    /* Сброс флага переполнения */
    TF1 = 0;

    /* Запуск таймера */
    TR1 = 1;
}

/* Чтение текущего значения Timer0 */
unsigned int timer0_read(void) {
    unsigned char high_byte, low_byte;

    /* Чтение значения таймера (сначала младший, потом старший байт) */
    low_byte = TL0;
    high_byte = TH0;

    return ((unsigned int)high_byte << 8) | low_byte;
}

/* Чтение текущего значения Timer1 */
unsigned int timer1_read(void) {
    return (unsigned int)TL1;
}

/* Тест основных операций с таймерами */
void test_timer_operations(void) {
    unsigned int initial_value, current_value;
    unsigned char delay_counter;

    /* Тест Timer0 */
    timer0_init(0x8000);  /* Загрузка значения 0x8000 */

    /* Небольшая задержка для работы таймера */
    for (delay_counter = 0; delay_counter < 100; delay_counter++) {
        /* Пустой цикл для задержки */
    }

    current_value = timer0_read();

    /* Проверка, что таймер работает (значение должно увеличиться) */
    if (current_value > 0x8000) {
        SET_BIT(P1, 0);  /* Timer0 работает корректно */
    }

    /* Тест Timer1 */
    timer1_init(0x80);  /* Загрузка значения 0x80 */

    /* Небольшая задержка */
    for (delay_counter = 0; delay_counter < 50; delay_counter++) {
        /* Пустой цикл для задержки */
    }

    current_value = timer1_read();

    /* Проверка работы Timer1 */
    if (current_value > 0x80) {
        SET_BIT(P1, 1);  /* Timer1 работает корректно */
    }
}

/* Тест флагов переполнения таймеров */
void test_timer_overflow(void) {
    unsigned char timeout_counter;

    /* Инициализация Timer0 с большим значением для быстрого переполнения */
    timer0_init(0xFFF0);

    /* Ожидание переполнения Timer0 */
    timeout_counter = 0;
    while (!TF0 && timeout_counter < 255) {
        timeout_counter++;
    }

    /* Проверка флага переполнения */
    if (TF0) {
        SET_BIT(P1, 2);  /* Переполнение Timer0 обнаружено */
        TF0 = 0;         /* Сброс флага */
    }

    /* Аналогичный тест для Timer1 */
    timer1_init(0xF0);

    timeout_counter = 0;
    while (!TF1 && timeout_counter < 255) {
        timeout_counter++;
    }

    if (TF1) {
        SET_BIT(P1, 3);  /* Переполнение Timer1 обнаружено */
        TF1 = 0;         /* Сброс флага */
    }
}

