        // Проверка статуса
        if (status & 0x01) {
            // Обработка принятых данных
            result = process_data(buffer, 16);

            switch (result) {
                case -1:
                    P2 = 0xFF;  // Все светодиоды включены
                    break;
                case 0:
                    P2 = 0xAA;  // Чередующийся паттерн
                    break;
                default:
                    P2 = 0x00;  // Все светодиоды выключены
                    break;
            }

            // Сброс флага
            status &= ~0x01;
        }

        // Задержка
        delay(100);
    }
}

