TMOD &= 0xF0;
TMOD |= 0x03;  /* Режим 3 для Timer0 */
TH0 = 0x80;
TL0 = 0x80;
TR0 = 1;
if (TR0) {
SET_BIT(P1, 7);  /* Режим 3 Timer0 активен */
}
}

