        return -1;
    } else if (sum > 500) {
        return 0;
    } else {
        return 1;
    }
}

// Основная функция
void main(void) {
    unsigned char buffer[16];
    int result;

    // Инициализация системы
    init_system();

    // Основной цикл
    while (1) {
        // Проверка статуса
        if (status & 0x01) {
            // Обработка принятых данных
            result = process_data(buffer, 16);

            switch (result) {
                case -1:
                    P2 = 0xFF;  // Все светодиоды включены
                    break;
                case 0:
                    P2 = 0xAA;  // Чередующийся паттерн
                    break;
                default:
                    P2 = 0x00;  // Все светодиоды выключены
                    break;
            }

            // Сброс флага
            status &= ~0x01;
        }

        // Задержка
        delay(100);
    }
}

