// P1.4 -- main
// P1.3 -- int0
// P1.2 -- int1

void f_int0(void) interrupt 0 // Instruction Pointer --> 0x0003h
{ 
	unsigned char i;
	P1 = 0x00;
	for(i = 0; i < 4; i++){
		P1_3 ^= 1; // toggle  --> 1
		wait();
		P1_3 ^= 1; // toggle  --> 0
		wait();
	}
	IE1 = 1;
}


void f_int1(void) interrupt 2 // Instruction Pointer --> 0x0013h
{
	unsigned char i;
	P1 = 0x00;
	for(i = 0; i < 5; i++){
		P1_2 ^= 1; // toggle  --> 1
		wait();
		P1_2 ^= 1; // toggle  --> 0
		wait();
	}
}

